(5552743, 803613, 54033, '<td valign="top">Nice shot, his left leg does not feel relaxed enough for contemplation, and the building in the middle rear has a very heavy presence. 6 and good luck.</td>', 'Nice shot, his left leg does not feel relaxed enough for contemplation, and the building in the middle rear has a very heavy presence. 6 and good luck.', '2009-07-01 10:07:07.000000', NULL, 1),
(5552747, 802411, 54033, '<td valign="top">A bit over processed.</td>', 'A bit over processed.', '2009-07-01 10:08:03.000000', NULL, 1),
(5552754, 803368, 101117, '<td valign="top">Interesting candid shot, not particularly outstanding foor FS, but makes me want ice cream!</td>', 'Interesting candid shot, not particularly outstanding foor FS, but makes me want ice cream!', '2009-07-01 10:10:37.000000', NULL, 1),
(5552756, 803405, 101117, '<td valign="top">interesting perspective. The top of the bridge is too "middle of the photo" for me. I would have liked to see it from a lower perspective. I realise you may have shot it this way to avoid the people, but including them from a low down perspective could have made it really interesting!</td>', 'interesting perspective. The top of the bridge is too "middle of the photo" for me. I would have liked to see it from a lower perspective. I realise you may have shot it this way to avoid the people, but including them from a low down perspective could have made it really interesting!', '2009-07-01 10:11:45.000000', NULL, 1),
(5552758, 803054, 101117, '<td valign="top">Nice straight forward animal shot. Feels just a touch blurred, like you''ve taken a small crop off a larger frame.</td>', 'Nice straight forward animal shot. Feels just a touch blurred, like you''ve taken a small crop off a larger frame.', '2009-07-01 10:12:44.000000', NULL, 1),
(5552760, 797967, 101117, '<td valign="top">Great colours and detail here. Interesting looking building, would like to be able to see more of it. Also, the colours in the building are really vivid, but the sky looks a little flat.</td>', 'Great colours and detail here. Interesting looking building, would like to be able to see more of it. Also, the colours in the building are really vivid, but the sky looks a little flat.', '2009-07-01 10:13:54.000000', NULL, 1),
(5552762, 802702, 101117, '<td valign="top">Nice shot here, love all the white buildings along the horizon. You have two competing subjects here though, the patterns in the water and the buildings. I can''t decide which one to look at as the main focus and I don''t think that''s helping my appreciation of the scene overall.</td>', 'Nice shot here, love all the white buildings along the horizon. You have two competing subjects here though, the patterns in the water and the buildings. I can''t decide which one to look at as the main focus and I don''t think that''s helping my appreciation of the scene overall.', '2009-07-01 10:15:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5552766, 802516, 101117, '<td valign="top">Good clear closeup spider shot. Nice detail and colours. Not outstanding particularly, especially in a free study, but well captured.</td>', 'Good clear closeup spider shot. Nice detail and colours. Not outstanding particularly, especially in a free study, but well captured.', '2009-07-01 10:16:03.000000', NULL, 1),
(5552768, 803474, 101117, '<td valign="top">This is postcard cute. You have a good composition in general, though I think for shots like this which are so obviously postcard like, a more centered approach does well.</td>', 'This is postcard cute. You have a good composition in general, though I think for shots like this which are so obviously postcard like, a more centered approach does well.', '2009-07-01 10:17:07.000000', NULL, 1),
(5552770, 802969, 101117, '<td valign="top">Wonderful vivid colours and nice reflection here. This is a really good capture with great detail.</td>', 'Wonderful vivid colours and nice reflection here. This is a really good capture with great detail.', '2009-07-01 10:18:33.000000', NULL, 1),
(5552774, 798496, 30049, '<td valign="top">This is nice.  Feels a little bit underexposed (wish it was a tad brighter is what I''m saying).  Good luck.</td>', 'This is nice.  Feels a little bit underexposed (wish it was a tad brighter is what I''m saying).  Good luck.', '2009-07-01 10:20:15.000000', NULL, 1),
(5552775, 802035, 101117, '<td valign="top">Nice to see a more unusual image in the free study. I love the contrasts and the strength of the overall image. <br/> <br/>The sky and the ground both have enough detail that they compete for my attention, but not in a bad way. This is the sort of thing you can see hanging in the reception of a large office block.</td>', 'Nice to see a more unusual image in the free study. I love the contrasts and the strength of the overall image.  The sky and the ground both have enough detail that they compete for my attention, but not in a bad way. This is the sort of thing you can see hanging in the reception of a large office block.', '2009-07-01 10:20:31.000000', NULL, 1),
(5552782, 803431, 30049, '<td valign="top">Very nice story telling!  I didn''t even need the title.  :-)</td>', 'Very nice story telling!  I didn''t even need the title.  :-)', '2009-07-01 10:22:44.000000', NULL, 1),
(5552786, 800091, 30049, '<td valign="top">Love the soft filtered look.  Very nice.</td>', 'Love the soft filtered look.  Very nice.', '2009-07-01 10:23:40.000000', NULL, 1),
(5552790, 801477, 30049, '<td valign="top">I love the mood you''ve captured here.  Well done!</td>', 'I love the mood you''ve captured here.  Well done!', '2009-07-01 10:24:40.000000', NULL, 1),
(5552791, 798755, 101117, '<td valign="top">This has the potential to be a nice image. The tones are good, it''s nice to see you didn''t oversaturate the sunset/sunrise as is often done, and the soft colours of the land are also nice.<br/> <br/>Overall I think the sun occupies too much of the image and there''s not a whole lot more of interest here. Also, the horizon is obviously tilted which could have been easily corrected. The little bit of detail you can see in the foreground makes me feel like you picked it up by accident because there''s not actually anything there that would add to the shot. Perhaps a similar shot from a lower angle would have given a bit of depth.</td>', 'This has the potential to be a nice image. The tones are good, it''s nice to see you didn''t oversaturate the sunset/sunrise as is often done, and the soft colours of the land are also nice. Overall I think the sun occupies too much of the image and there''s not a whole lot more of interest here. Also, the horizon is obviously tilted which could have been easily corrected. The little bit of detail you can see in the foreground makes me feel like you picked it up by accident because there''s not actually anything there that would add to the shot. Perhaps a similar shot from a lower angle would have given a bit of depth.', '2009-07-01 10:24:51.000000', NULL, 1),
(5552797, 802334, 101117, '<td valign="top">Very cute, with nice colours and good exposure. All the other details in the frame don''t help though. The bricks, ground etc all take away from the focus, and because the image moves away as you look to the right, it draws my eye in that direction away from the kittens.</td>', 'Very cute, with nice colours and good exposure. All the other details in the frame don''t help though. The bricks, ground etc all take away from the focus, and because the image moves away as you look to the right, it draws my eye in that direction away from the kittens.', '2009-07-01 10:27:16.000000', NULL, 1),
(5552799, 803511, 101117, '<td valign="top">This is a very nice capture with great colours and exposure. I love the back / top lighting in this one, it really adds depth to the scene.<br/> <br/>Excellent detail for the main subject with a nice OOF background, great work!</td>', 'This is a very nice capture with great colours and exposure. I love the back / top lighting in this one, it really adds depth to the scene. Excellent detail for the main subject with a nice OOF background, great work!', '2009-07-01 10:29:00.000000', NULL, 1),
(5552802, 803454, 101117, '<td valign="top">Very moody atmospheric shot. Love the silhouette with only the arm in the light. Don''t imagine this will do great here, but I really like it, great work!</td>', 'Very moody atmospheric shot. Love the silhouette with only the arm in the light. Don''t imagine this will do great here, but I really like it, great work!', '2009-07-01 10:30:08.000000', NULL, 1),
(5552812, 803281, 101117, '<td valign="top">This is a really nice wonderfully lit portrait! The skin tones are wonderful and very natural looking. Either your model has great skin or you''ve done a great job editing. Your lighting is also great and works well with the tones.<br/> <br/>My only minor complaint about the whole shot is the stray hair to the left. It''s not quite enough hair to add "windswept and interesting" so ends up just looking a little untidy.</td>', 'This is a really nice wonderfully lit portrait! The skin tones are wonderful and very natural looking. Either your model has great skin or you''ve done a great job editing. Your lighting is also great and works well with the tones. My only minor complaint about the whole shot is the stray hair to the left. It''s not quite enough hair to add "windswept and interesting" so ends up just looking a little untidy.', '2009-07-01 10:33:12.000000', NULL, 1),
(5552820, 798854, 101117, '<td valign="top">This is almost great, but for me not quite right. It feels slightly "over posed" for a supposedly candid shot (I realise it''s not candid, but you know what I mean).<br/> <br/>Also, I think because you have partial silhouette for the faces but then detail in the dress it doesn''t quite work. A little bit of fill light, perhaps even from a very subtle reflector would have made the world of difference for me.</td>', 'This is almost great, but for me not quite right. It feels slightly "over posed" for a supposedly candid shot (I realise it''s not candid, but you know what I mean). Also, I think because you have partial silhouette for the faces but then detail in the dress it doesn''t quite work. A little bit of fill light, perhaps even from a very subtle reflector would have made the world of difference for me.', '2009-07-01 10:37:49.000000', NULL, 1),
(5552827, 803237, 101117, '<td valign="top">Good shot, very peaceful feeling. I think it misses out on being great by the "too close to center" horizon, and for me a bit too much space around the buildings. I realise it''s a big landscape shot, but you have a subject there and I would have preferred to see it a little better.</td>', 'Good shot, very peaceful feeling. I think it misses out on being great by the "too close to center" horizon, and for me a bit too much space around the buildings. I realise it''s a big landscape shot, but you have a subject there and I would have preferred to see it a little better.', '2009-07-01 10:40:02.000000', NULL, 1),
(5552835, 803369, 101117, '<td valign="top">Nice landscape shot with good colours which are reflected nicely on the water. Not so sure about the foreground object, I''m sure it has something to do with the title but I don''t really get it, and I''m not convinced that the plant / tree adds anything at all.<br/> <br/>I do think the foreground would be a little bland without something, but I don''t think the something you have is what it needs.</td>', 'Nice landscape shot with good colours which are reflected nicely on the water. Not so sure about the foreground object, I''m sure it has something to do with the title but I don''t really get it, and I''m not convinced that the plant / tree adds anything at all. I do think the foreground would be a little bland without something, but I don''t think the something you have is what it needs.', '2009-07-01 10:43:20.000000', NULL, 1),
(5552850, 802428, 101117, '<td valign="top">I was looking at that thinking, "is it a rock, is it some sort of weird alien object, why is it triangular..." and then I read the title and figured it all out.<br/> <br/>It''s a very centered composition, and while the pier off to the left and the people way in the distance help it slightly, I still feel it looks a bit "snapshottish".</td>', 'I was looking at that thinking, "is it a rock, is it some sort of weird alien object, why is it triangular..." and then I read the title and figured it all out. It''s a very centered composition, and while the pier off to the left and the people way in the distance help it slightly, I still feel it looks a bit "snapshottish".', '2009-07-01 10:47:48.000000', NULL, 1),
(5552855, 803627, 101117, '<td valign="top">Wonderful landscape shot with great processing. The tree and the plants almost seem to be glowing, yet neither seems overdone. Love the way the clouds seem to be rolling over the mountains, and the sand / rock off to the left of the frame has great patterns in it. This has got to be HDR to have such a good range of exposure!<br/> <br/>I would come here just to sit and look at this place if I lived near it!</td>', 'Wonderful landscape shot with great processing. The tree and the plants almost seem to be glowing, yet neither seems overdone. Love the way the clouds seem to be rolling over the mountains, and the sand / rock off to the left of the frame has great patterns in it. This has got to be HDR to have such a good range of exposure! I would come here just to sit and look at this place if I lived near it!', '2009-07-01 10:49:59.000000', NULL, 1),
(5552857, 802863, 101117, '<td valign="top">Great unusual portrait, my immediate thought was IRISH! Love the colours and detail. Whatever that is in the background is a bit distracting though.</td>', 'Great unusual portrait, my immediate thought was IRISH! Love the colours and detail. Whatever that is in the background is a bit distracting though.', '2009-07-01 10:51:11.000000', NULL, 1),
(5552859, 803565, 101117, '<td valign="top">Nice model shot, great hair!!!<br/> <br/>The contrast of the glamor model and abandoned background is good, and the kind of thing you see a lot in fashion magazines just now.<br/> <br/>I''m giving this an 8, and that''s only because there''s something that isn''t quite sitting right with me, I''m not sure entirely what it is, but I just don''t feel strongly enough about the shot to give it higher.</td>', 'Nice model shot, great hair!!! The contrast of the glamor model and abandoned background is good, and the kind of thing you see a lot in fashion magazines just now. I''m giving this an 8, and that''s only because there''s something that isn''t quite sitting right with me, I''m not sure entirely what it is, but I just don''t feel strongly enough about the shot to give it higher.', '2009-07-01 10:54:54.000000', NULL, 1),
(5552861, 802406, 101117, '<td valign="top">Nice calendar style shot. Good colours and composition. Perhaps just a touch oversaturated in the sky for me.</td>', 'Nice calendar style shot. Good colours and composition. Perhaps just a touch oversaturated in the sky for me.', '2009-07-01 10:55:50.000000', NULL, 1),
(5552865, 803226, 101117, '<td valign="top">What a great unusual shot, I would love to see more of this. The lines are wondeful and they lead you nicely down into the shot.<br/> <br/>If I lived near landscapes like this I would be there all the time trying to get shots just like this!</td>', 'What a great unusual shot, I would love to see more of this. The lines are wondeful and they lead you nicely down into the shot. If I lived near landscapes like this I would be there all the time trying to get shots just like this!', '2009-07-01 10:57:05.000000', NULL, 1),
(5552867, 796866, 101117, '<td valign="top">I realised recently I talk about CD''s the same way I used to talk about LP''s. Nice reminder of them but not really an outstanding shot for a free study.</td>', 'I realised recently I talk about CD''s the same way I used to talk about LP''s. Nice reminder of them but not really an outstanding shot for a free study.', '2009-07-01 10:58:16.000000', NULL, 1),
(5552869, 800259, 101117, '<td valign="top">Nice model shot with an interesting background. Unfortunately she''s glowing, and I don''t mean that in a "great skin tones" kind of way. There''s an aura all around her from the processing, feels kinda like you finished work on the model and then didn''t bother with the background.<br/> <br/>I''ll give this a 6 overall, few points knocked off for the glowing girl!</td>', 'Nice model shot with an interesting background. Unfortunately she''s glowing, and I don''t mean that in a "great skin tones" kind of way. There''s an aura all around her from the processing, feels kinda like you finished work on the model and then didn''t bother with the background. I''ll give this a 6 overall, few points knocked off for the glowing girl!', '2009-07-01 11:00:30.000000', NULL, 1),
(5552870, 803626, 57447, '<td valign="top">This is sooo good!</td>', 'This is sooo good!', '2009-07-01 11:00:52.000000', NULL, 1),
