(5554052, 803582, 103032, '<td valign="top">First impressions, your processing give this a "lithographic" feel to the image.  I''m guessing from the title, it might be around the Supreme Court???  Composition wise, maybe paying a little more attention to your position, a step or two to your left to center the gavel in the middle of the columns in the background for better symmetry of the picture; and correct the tilt of the pic, it''s just a touch off.  That''s nit picking.  Otherwise, it''s an interesting image.</td>', 'First impressions, your processing give this a "lithographic" feel to the image.  I''m guessing from the title, it might be around the Supreme Court???  Composition wise, maybe paying a little more attention to your position, a step or two to your left to center the gavel in the middle of the columns in the background for better symmetry of the picture; and correct the tilt of the pic, it''s just a touch off.  That''s nit picking.  Otherwise, it''s an interesting image.', '2009-07-01 17:29:17.000000', NULL, 1),
(5554060, 803299, 43774, '<td valign="top">I''ve never tried to capture lightning before, we don''t get a lot of it around here. Good for you for being able to photograph it.</td>', 'I''ve never tried to capture lightning before, we don''t get a lot of it around here. Good for you for being able to photograph it.', '2009-07-01 17:30:06.000000', NULL, 1),
(5554073, 803618, 43774, '<td valign="top">It does look like a pearl, good exposure.</td>', 'It does look like a pearl, good exposure.', '2009-07-01 17:31:55.000000', NULL, 1),
(5554078, 800739, 43774, '<td valign="top">Good use of blur to create an impressionistic style photograph.</td>', 'Good use of blur to create an impressionistic style photograph.', '2009-07-01 17:32:33.000000', NULL, 1),
(5554081, 798843, 92577, '<td valign="top">ol'' red-eye''s back in town - great shot</td>', 'ol'' red-eye''s back in town - great shot', '2009-07-01 17:32:53.000000', NULL, 1),
(5554085, 803536, 43774, '<td valign="top">The old dilapidated building and the sense of movement gives this a creepy feeling.</td>', 'The old dilapidated building and the sense of movement gives this a creepy feeling.', '2009-07-01 17:34:23.000000', NULL, 1),
