(5554322, 799686, 15711, '<td valign="top">What a beautiful example of narrow DOF.  It''s a standout on the page.  Had I not known, I''d think "ursula."  Way to go.  Hope it does well. Good luck.</td>', 'What a beautiful example of narrow DOF.  It''s a standout on the page.  Had I not known, I''d think "ursula."  Way to go.  Hope it does well. Good luck.', '2009-07-01 18:56:12.000000', NULL, 1),
(5554329, 802501, 15711, '<td valign="top">Is his tongue really that purple?  Excellent focus.  Love it.</td>', 'Is his tongue really that purple?  Excellent focus.  Love it.', '2009-07-01 18:57:11.000000', NULL, 1),
(5554343, 803555, 43774, '<td valign="top">A bit dark for my tastes.</td>', 'A bit dark for my tastes.', '2009-07-01 19:00:07.000000', NULL, 1),
(5554348, 803214, 43774, '<td valign="top">Very cool. A bit dull, could use some brightening up. I''d like to see more of that fantastic city in the background and less sky.</td>', 'Very cool. A bit dull, could use some brightening up. I''d like to see more of that fantastic city in the background and less sky.', '2009-07-01 19:01:15.000000', NULL, 1),
(5554350, 803172, 43774, '<td valign="top">The joy on his face speaks volumes. Image is not quite in focus though.</td>', 'The joy on his face speaks volumes. Image is not quite in focus though.', '2009-07-01 19:01:36.000000', NULL, 1),
(5554358, 795726, 43774, '<td valign="top">I think the sun flare ruins this shot, sorry.</td>', 'I think the sun flare ruins this shot, sorry.', '2009-07-01 19:02:29.000000', NULL, 1),
(5554370, 803582, 98339, '<td valign="top">this shot has so many elements in it to make it quite the superior shot...I''m not sure what happened (probably direct harsh sunlight) but the center part of your shot is devoid of lines (like you see in the top part) IMO (and that does not count for much..) I really think that a gradient applied to the center would have really helped to bring back the detail that was/is lost in the harsh sunlight..given that...I love the tones in the top and the bottom of the shot but not the center...</td>', 'this shot has so many elements in it to make it quite the superior shot...I''m not sure what happened (probably direct harsh sunlight) but the center part of your shot is devoid of lines (like you see in the top part) IMO (and that does not count for much..) I really think that a gradient applied to the center would have really helped to bring back the detail that was/is lost in the harsh sunlight..given that...I love the tones in the top and the bottom of the shot but not the center...', '2009-07-01 19:07:05.000000', NULL, 1),
(5554372, 803021, 98339, '<td valign="top">oh, sunflowers...such happy flowers...this would be an excellent choice for doing an overlay one it...such wonderful bright colors...well done</td>', 'oh, sunflowers...such happy flowers...this would be an excellent choice for doing an overlay one it...such wonderful bright colors...well done', '2009-07-01 19:07:47.000000', NULL, 1),
(5554374, 800846, 98339, '<td valign="top">boy that bee is humming...excellent capture...full of detail and color</td>', 'boy that bee is humming...excellent capture...full of detail and color', '2009-07-01 19:08:28.000000', NULL, 1),
