(5554486, 803613, 43774, '<td valign="top">Interesting image with professional lighting but way oversharpened which really detracts from the photo.</td>', 'Interesting image with professional lighting but way oversharpened which really detracts from the photo.', '2009-07-01 19:45:37.000000', NULL, 1),
(5554489, 803113, 43774, '<td valign="top">Interesting DOF (top and bottom in focus but not the middle), colourful and quirky.</td>', 'Interesting DOF (top and bottom in focus but not the middle), colourful and quirky.', '2009-07-01 19:46:34.000000', NULL, 1),
