(5556502, 800888, 43774, '<td valign="top">Is this the "Tulip stairs" in a museum in Greenwich? Because if it is I am insanely jealous!!! I was there last September and I wasn''t allowed to bring my camera in, I would have had to leave it at the desk. So I didn''t go see it!</td>', 'Is this the "Tulip stairs" in a museum in Greenwich? Because if it is I am insanely jealous!!! I was there last September and I wasn''t allowed to bring my camera in, I would have had to leave it at the desk. So I didn''t go see it!', '2009-07-02 19:49:57.000000', NULL, 1),
(5556503, 800846, 43774, '<td valign="top">Very sharp, great detail, especially in the moving bee.</td>', 'Very sharp, great detail, especially in the moving bee.', '2009-07-02 19:49:59.000000', NULL, 1),
