(5556538, 803557, 43774, '<td valign="top">I''ve never seen cows in real life with horns like that before, pretty cool.</td>', 'I''ve never seen cows in real life with horns like that before, pretty cool.', '2009-07-02 19:52:57.000000', NULL, 1),
(5556539, 798843, 43774, '<td valign="top">Amazing detail, wow.</td>', 'Amazing detail, wow.', '2009-07-02 19:53:14.000000', NULL, 1),
