(5556611, 803542, 15711, '<td valign="top">That''s really beautiful.</td>', 'That''s really beautiful.', '2009-07-02 20:57:05.000000', NULL, 1),
(5556618, 802602, 55956, '<td valign="top">where has been captured this image? it seems a real scene of war theater. beautiful the cloud of sand in the backside of the car, there is a great contrast between the scene and the clean skin of the girl, securely this is a photoshop work on the image but it is a good contrast. the colour seems with to much yellow(but the environment have securely a yellow channel with high values) the sky have a natural color that come from the sand and the umidity(I think) 10</td>', 'where has been captured this image? it seems a real scene of war theater. beautiful the cloud of sand in the backside of the car, there is a great contrast between the scene and the clean skin of the girl, securely this is a photoshop work on the image but it is a good contrast. the colour seems with to much yellow(but the environment have securely a yellow channel with high values) the sky have a natural color that come from the sand and the umidity(I think) 10', '2009-07-02 21:05:44.000000', NULL, 1),
(5556619, 797073, 55956, '<td valign="top">high wow effect and great image.</td>', 'high wow effect and great image.', '2009-07-02 21:06:17.000000', NULL, 1),
