(5557908, 803463, 43774, '<td valign="top">I really like the composition, I like the detail and colours. The glow and halo around the edges is not that appealing to me.</td>', 'I really like the composition, I like the detail and colours. The glow and halo around the edges is not that appealing to me.', '2009-07-03 14:01:05.000000', NULL, 1),
(5557909, 803434, 43774, '<td valign="top">He has an amazing face.</td>', 'He has an amazing face.', '2009-07-03 14:01:26.000000', NULL, 1),
