(5558936, 800259, 76335, '<td valign="top">Interesting pose/angle, great colors. Surely her name could have been the title.</td>', 'Interesting pose/angle, great colors. Surely her name could have been the title.', '2009-07-04 11:29:32.000000', NULL, 1),
(5558937, 798843, 76335, '<td valign="top">Points for the title alone! The shot isn''t half bad either (it''s not even a fraction bad). Great!</td>', 'Points for the title alone! The shot isn''t half bad either (it''s not even a fraction bad). Great!', '2009-07-04 11:30:22.000000', NULL, 1),
(5558939, 797458, 76335, '<td valign="top">Well seen, but <i>way</i> overprocessed. Instead of cranking up saturation (it''s too much), consider monochrome. It''s the pattern you want to show off; the color is just a distraction to that end. My $0.02 anyway.</td>', 'Well seen, but way overprocessed. Instead of cranking up saturation (it''s too much), consider monochrome. It''s the pattern you want to show off; the color is just a distraction to that end. My $0.02 anyway.', '2009-07-04 11:32:05.000000', NULL, 1),
