(5558959, 802645, 76335, '<td valign="top">Perhaps cropping the underexposed left edge of the frame and/or converting to black and white would have given more impact. Good comp anyway.</td>', 'Perhaps cropping the underexposed left edge of the frame and/or converting to black and white would have given more impact. Good comp anyway.', '2009-07-04 11:40:20.000000', NULL, 1),
(5558960, 802882, 76335, '<td valign="top">Beautifully processed.</td>', 'Beautifully processed.', '2009-07-04 11:41:07.000000', NULL, 1),
