(5558967, 803419, 76335, '<td valign="top">Fabulous! The black and white and high contrast do wonders to show off all that excellent geometry.</td>', 'Fabulous! The black and white and high contrast do wonders to show off all that excellent geometry.', '2009-07-04 11:43:52.000000', NULL, 1),
