(5559640, 803246, 38162, '<td valign="top">excellent mood and tonality.  litter removal post capture would help, imo.  Im sure you can argue the opposite.  gl</td>', 'excellent mood and tonality.  litter removal post capture would help, imo.  Im sure you can argue the opposite.  gl', '2009-07-04 23:39:53.000000', NULL, 1),
(5559641, 800362, 38162, '<td valign="top">border detracts.</td>', 'border detracts.', '2009-07-04 23:40:07.000000', NULL, 1),
(5559642, 802432, 101117, '<td valign="top">I like the concept here, but I don''t think you''ve pulled it off quite right. <br/> <br/>I like the angle and the composition, but the fact that I can''t quite see the two figures is frustrating. I think either they are silhouetted or properly visible, but you haven''t quite done either here.</td>', 'I like the concept here, but I don''t think you''ve pulled it off quite right.  I like the angle and the composition, but the fact that I can''t quite see the two figures is frustrating. I think either they are silhouetted or properly visible, but you haven''t quite done either here.', '2009-07-04 23:40:49.000000', NULL, 1),
(5559646, 802823, 38162, '<td valign="top">not a fan of that border.  super capture.</td>', 'not a fan of that border.  super capture.', '2009-07-04 23:43:33.000000', NULL, 1),
(5559648, 799269, 101117, '<td valign="top">Nice macro flower shot. Good colours and light. Not sure how much I like the ones in the background though, they seem to be falling out of the shot.</td>', 'Nice macro flower shot. Good colours and light. Not sure how much I like the ones in the background though, they seem to be falling out of the shot.', '2009-07-04 23:44:16.000000', NULL, 1),
(5559649, 803511, 38162, '<td valign="top">border detracts.</td>', 'border detracts.', '2009-07-04 23:44:16.000000', NULL, 1),
(5559652, 803448, 101117, '<td valign="top">Interesting and colourful shot. These things are always great fun for long exposures! I particularly like the way this one has turned out, it looks like a bit tray with lots of little segments for holding stuff!<br/> <br/>Nice composition and I like the reflection. I think it''s a shame you have three items on the skyline competing for attention, the wheel, the tent and the stadium.</td>', 'Interesting and colourful shot. These things are always great fun for long exposures! I particularly like the way this one has turned out, it looks like a bit tray with lots of little segments for holding stuff! Nice composition and I like the reflection. I think it''s a shame you have three items on the skyline competing for attention, the wheel, the tent and the stadium.', '2009-07-04 23:46:56.000000', NULL, 1),
(5559653, 799129, 38162, '<td valign="top">windy title aside, a very powerful image.</td>', 'windy title aside, a very powerful image.', '2009-07-04 23:48:53.000000', NULL, 1),
(5559654, 803004, 101117, '<td valign="top">These are always nice images, though something you see a lot of here so never particularly outstanding when you come across them.<br/> <br/>You have nice tones in this one, it''s a pleasant break away from the over saturated blues and reds. It doesn''t particularly feel like a ''sunset'' shot, probably because of how brightly lit it is.</td>', 'These are always nice images, though something you see a lot of here so never particularly outstanding when you come across them. You have nice tones in this one, it''s a pleasant break away from the over saturated blues and reds. It doesn''t particularly feel like a ''sunset'' shot, probably because of how brightly lit it is.', '2009-07-04 23:49:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5559658, 803545, 38162, '<td valign="top">shouldnt the image tell the story?</td>', 'shouldnt the image tell the story?', '2009-07-04 23:52:19.000000', NULL, 1),
(5559659, 800379, 101117, '<td valign="top">This to me is really just a snapshot of a horse. Most of the frame, including the horse itself is too dark to make out properly and the well exposed outside part doesn''t really hold any interest.</td>', 'This to me is really just a snapshot of a horse. Most of the frame, including the horse itself is too dark to make out properly and the well exposed outside part doesn''t really hold any interest.', '2009-07-04 23:52:40.000000', NULL, 1),
(5559663, 799762, 101117, '<td valign="top">This is a very nice moody image. I love the dark clouds overhead and the way the landscape fades into them in the distance.<br/> <br/>I can''t figure out why you left the people in along the bottom right of the shot and didn''t just crop that bit out. I losing a little along the bottom would have been much better than having the heads all poking into the frame!</td>', 'This is a very nice moody image. I love the dark clouds overhead and the way the landscape fades into them in the distance. I can''t figure out why you left the people in along the bottom right of the shot and didn''t just crop that bit out. I losing a little along the bottom would have been much better than having the heads all poking into the frame!', '2009-07-04 23:58:09.000000', NULL, 1),
(5559666, 803299, 101117, '<td valign="top">It''s always good fun capturing lightning, and while you''ve managed to do that here, I don''t think there''s really anything of interest.<br/> <br/>There''s no real context, you can''t see what the lighting is over. Also the shot is quite grainy and blurred as if you''ve cropped just that little section out of a much larger frame.</td>', 'It''s always good fun capturing lightning, and while you''ve managed to do that here, I don''t think there''s really anything of interest. There''s no real context, you can''t see what the lighting is over. Also the shot is quite grainy and blurred as if you''ve cropped just that little section out of a much larger frame.', '2009-07-04 23:59:22.000000', NULL, 1),
(5559669, 803555, 101117, '<td valign="top">Interesting and unusual bird shot. I like what you''ve done here a lot, but I''m just not sure if there''s enough contrast between the bird and the background.<br/> <br/>I think the problem might be the white area you have at the top left of the frame, it draws my attention because of the fact that the rest of it is so dark. When I cover that part with my hand the whole shot looks a lot better and the bird stands out much more clearly against the background.</td>', 'Interesting and unusual bird shot. I like what you''ve done here a lot, but I''m just not sure if there''s enough contrast between the bird and the background. I think the problem might be the white area you have at the top left of the frame, it draws my attention because of the fact that the rest of it is so dark. When I cover that part with my hand the whole shot looks a lot better and the bird stands out much more clearly against the background.', '2009-07-05 00:01:46.000000', NULL, 1),
(5559673, 800530, 38162, '<td valign="top">crop and border hurts this one.</td>', 'crop and border hurts this one.', '2009-07-05 00:02:58.000000', NULL, 1),
(5559675, 801464, 38162, '<td valign="top">border detracts.</td>', 'border detracts.', '2009-07-05 00:06:14.000000', NULL, 1),
(5559676, 803116, 101117, '<td valign="top">I never like partial desat shots, and this one falls right in there.<br/> <br/>Taking an objective view, the composition is quite nice, but you have made the flowers the main subject by removing the colour from the bride, yet the flowers seem to be slightly out of focus.<br/> <br/>The area of the shot which is in B&amp;W seems to have a lot of grain. This might work if it was the whole shot, but because of the coloured flowers it has actually ended up feeling like you have two separate images, one superimposed on top of the other.</td>', 'I never like partial desat shots, and this one falls right in there. Taking an objective view, the composition is quite nice, but you have made the flowers the main subject by removing the colour from the bride, yet the flowers seem to be slightly out of focus. The area of the shot which is in B&W seems to have a lot of grain. This might work if it was the whole shot, but because of the coloured flowers it has actually ended up feeling like you have two separate images, one superimposed on top of the other.', '2009-07-05 00:06:31.000000', NULL, 1),
(5559679, 803146, 38162, '<td valign="top">some put the quotes like this: The new "Yankee Stadium" - ahem.  */*  gl</td>', 'some put the quotes like this: The new "Yankee Stadium" - ahem.  */*  gl', '2009-07-05 00:07:52.000000', NULL, 1),
(5559680, 803390, 101117, '<td valign="top">Very nice moody shot. I love the two figures against the brightest part of the background, and the fact that the are sitting between the large dark cloud and it''s reflection.<br/> <br/>The composition and the tones are all excellent, I don''t mind the centered horizon at all here, I think it works for this shot because of all the other elements. 10 from me.</td>', 'Very nice moody shot. I love the two figures against the brightest part of the background, and the fact that the are sitting between the large dark cloud and it''s reflection. The composition and the tones are all excellent, I don''t mind the centered horizon at all here, I think it works for this shot because of all the other elements. 10 from me.', '2009-07-05 00:08:42.000000', NULL, 1),
