(5560813, 803172, 76335, '<td valign="top">Nice moment but maybe a tad overprocessed.</td>', 'Nice moment but maybe a tad overprocessed.', '2009-07-05 20:54:28.000000', NULL, 1),
(5560814, 799082, 76335, '<td valign="top">Wonderful lines and rhythm. Tempted to say this would do better in black and white, but the colors are quite appealing on second look.</td>', 'Wonderful lines and rhythm. Tempted to say this would do better in black and white, but the colors are quite appealing on second look.', '2009-07-05 20:55:13.000000', NULL, 1),
