(5562693, 797581, 108320, '<td valign="top">Very nice scenery, good framing &amp; mood. good perspective &amp; colors! Overall very nice. Seems a bit tilted to the right but that might be the poles not being straight.</td>', 'Very nice scenery, good framing & mood. good perspective & colors! Overall very nice. Seems a bit tilted to the right but that might be the poles not being straight.', '2009-07-07 05:47:08.000000', NULL, 1),
(5562703, 800530, 108320, '<td valign="top">Amazing shot. Perfect colors. interesting angle.</td>', 'Amazing shot. Perfect colors. interesting angle.', '2009-07-07 05:55:50.000000', NULL, 1),
(5562745, 796473, 79955, '<td valign="top">wonderful details, unique composition IMO. 8</td>', 'wonderful details, unique composition IMO. 8', '2009-07-07 07:51:44.000000', NULL, 1),
