INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5562953, 803129, 65234, '<td valign="top">Lovely textures.</td>', 'Lovely textures.', '2009-07-07 12:46:12.000000', NULL, 1),
(5562954, 803488, 65234, '<td valign="top">Love the colors and the motion in the clouds.</td>', 'Love the colors and the motion in the clouds.', '2009-07-07 12:47:18.000000', NULL, 1),
(5562955, 803457, 65234, '<td valign="top">Cool!  Really fun abstract :-)</td>', 'Cool!  Really fun abstract :-)', '2009-07-07 12:48:04.000000', NULL, 1),
(5562958, 803248, 65234, '<td valign="top">Exposure is perfect and composition interests me.  Colors are a bit oversaturated for my taste.</td>', 'Exposure is perfect and composition interests me.  Colors are a bit oversaturated for my taste.', '2009-07-07 12:50:56.000000', NULL, 1),
(5562963, 803270, 90944, '<td valign="top">I love the light, great capture!</td>', 'I love the light, great capture!', '2009-07-07 12:52:38.000000', NULL, 1),
(5562964, 803428, 65234, '<td valign="top">Bizarre froggy creature!  B&amp;W emphasizes his shape nicely.</td>', 'Bizarre froggy creature!  B&W emphasizes his shape nicely.', '2009-07-07 12:52:53.000000', NULL, 1),
(5562967, 803233, 65234, '<td valign="top">DOF and detail are spot on.  I think Mom could use a little more headroom in the composition but I am still very jealous that you got this shot!  I would love to see something like this in person someday, but all I ever see is adult deer.  Thanks for sharing this :-)</td>', 'DOF and detail are spot on.  I think Mom could use a little more headroom in the composition but I am still very jealous that you got this shot!  I would love to see something like this in person someday, but all I ever see is adult deer.  Thanks for sharing this :-)', '2009-07-07 12:55:09.000000', NULL, 1),
(5562969, 802357, 65234, '<td valign="top">Puffins :-)))))))  They are just so cute.  Love the composition here; it''s making me smile.</td>', 'Puffins :-)))))))  They are just so cute.  Love the composition here; it''s making me smile.', '2009-07-07 12:55:53.000000', NULL, 1),
(5562972, 803639, 65234, '<td valign="top">Looks like a scene from a sci-fi movie.</td>', 'Looks like a scene from a sci-fi movie.', '2009-07-07 12:58:16.000000', NULL, 1),
(5562973, 802334, 65234, '<td valign="top">I could watch kittens play all day!  Such cute little things, and nice composition here.</td>', 'I could watch kittens play all day!  Such cute little things, and nice composition here.', '2009-07-07 12:59:22.000000', NULL, 1),
(5562974, 801434, 61961, '<td valign="top">I thought this might show up in the Free Study after I looked for it and couldn''t find it in your portfolio!  A great shot, Steve.</td>', 'I thought this might show up in the Free Study after I looked for it and couldn''t find it in your portfolio!  A great shot, Steve.', '2009-07-07 12:59:31.000000', NULL, 1),
(5562978, 802645, 65234, '<td valign="top">Interesting place; love the color and sense of antiquity.  From this perspective I''m having a hard time figuring out exactly what the object is in the upper middle of the image.  A ceiling we''re underneath?  It almost looks like a flattish stone stuck vertically into the top of that house.  Weird optical effect (or .. it''s just me).</td>', 'Interesting place; love the color and sense of antiquity.  From this perspective I''m having a hard time figuring out exactly what the object is in the upper middle of the image.  A ceiling we''re underneath?  It almost looks like a flattish stone stuck vertically into the top of that house.  Weird optical effect (or .. it''s just me).', '2009-07-07 13:03:46.000000', NULL, 1),
(5562979, 797692, 65234, '<td valign="top">Very cute!  Snail looks like he needed just a touch more DOF to get his whole shell in focus.</td>', 'Very cute!  Snail looks like he needed just a touch more DOF to get his whole shell in focus.', '2009-07-07 13:04:33.000000', NULL, 1),
(5562980, 803235, 65234, '<td valign="top">Lovely color and I like the perspective and DOF.</td>', 'Lovely color and I like the perspective and DOF.', '2009-07-07 13:05:14.000000', NULL, 1),
(5562984, 802313, 65234, '<td valign="top">Water looks invitingly clean.  Nice colors, not overdone.</td>', 'Water looks invitingly clean.  Nice colors, not overdone.', '2009-07-07 13:06:26.000000', NULL, 1),
(5562989, 802501, 65234, '<td valign="top">How funny is it that someone else had the same idea, but with a housecat?!  Looks like he''s all ready for a dental exam ;-)  Tons of detail here.  Some of the whites on him are tinted cyan; I''d desaturate them, and maybe give him a virtual tooth cleaning to really make them stand out.</td>', 'How funny is it that someone else had the same idea, but with a housecat?!  Looks like he''s all ready for a dental exam ;-)  Tons of detail here.  Some of the whites on him are tinted cyan; I''d desaturate them, and maybe give him a virtual tooth cleaning to really make them stand out.', '2009-07-07 13:11:02.000000', NULL, 1),
(5562991, 803312, 65234, '<td valign="top">Very cool capture!</td>', 'Very cool capture!', '2009-07-07 13:11:51.000000', NULL, 1),
(5562994, 802028, 65234, '<td valign="top">Astounding clarity on those wings!  Wow.</td>', 'Astounding clarity on those wings!  Wow.', '2009-07-07 13:14:04.000000', NULL, 1),
(5562998, 796473, 65234, '<td valign="top">GREAT clarity and detail!  These guys tend to be a bit shier than some of the other woodpeckers who come to visit here, so I am quite impressed.</td>', 'GREAT clarity and detail!  These guys tend to be a bit shier than some of the other woodpeckers who come to visit here, so I am quite impressed.', '2009-07-07 13:19:23.000000', NULL, 1),
