(5564592, 796473, 106109, '<td valign="top">Thanks to all of you for such nice comments. I appreciate them.  --Rick</td>', 'Thanks to all of you for such nice comments. I appreciate them.  --Rick', '2009-07-08 04:29:28.000000', NULL, 0),
